nextflow_process {

    name "Test Process PARABRICKS_FQ2BAM"
    script "../main.nf"
    process "PARABRICKS_FQ2BAM"

    tag "bwa/index"
    tag "modules"
    tag "parabricks/fq2bam"
    tag "modules_nfcore"
    tag "parabricks"
    tag "gpu"

    config './nextflow.config'

    setup {
        run("BWA_INDEX") {
            script "../../../bwa/index/main.nf"
            process {
                """
                input[0] = Channel.of([
                    [ id:'test' ], // meta map
                    file('https://github.com/nf-core/test-datasets/raw/methylseq/reference/genome.fa', checkIfExists: true)
                ])
                input[1] = []
                """
            }
        }

        run("BWA_INDEX", alias: 'BWA_INDEX_PE') {
            script "../../../bwa/index/main.nf"
            process {
                """
                input[0] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[1] = []
                """
            }
        }

        run("BWA_INDEX", alias: 'BWA_INDEX_CRAM') {
            script "../../../bwa/index/main.nf"
            process {
                """
                input[0] = [
                    [id: 'test'],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }
    }

    test("SRR389222 - fastq - se") {

        config './nextflow.config'

        when {
            params {
                module_args = ''
                bwa_prefix = 'genome.fa'
            }
            process {
                """
                input[0] = Channel.of([
				    [ id:'test', single_end:true ], // meta map
				    [
				        file('https://github.com/nf-core/test-datasets/raw/methylseq/testdata/SRR389222_sub1.fastq.gz', checkIfExists: true)
				    ]
				])
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file('https://github.com/nf-core/test-datasets/raw/methylseq/reference/genome.fa', checkIfExists: true)
                ])
				input[2] = BWA_INDEX.out.index
                input[3] = [ [], [] ]
                input[4] = [ [], [], [] ]
                input[5] = 'bam'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    file(process.out.bai[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("SRR389222 - fastq - se - stub") {

        options '-stub'

        when {
            params {
                module_args = ''
                bwa_prefix = ''
            }
            process {
                """
                input[0] = Channel.of([
				    [ id:'test', single_end:true ], // meta map
				    [
				        file('https://github.com/nf-core/test-datasets/raw/methylseq/testdata/SRR389222_sub1.fastq.gz', checkIfExists: true)
				    ]
				])
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file('https://github.com/nf-core/test-datasets/raw/methylseq/reference/genome.fa', checkIfExists: true)
                ])
				input[2] = BWA_INDEX.out.index
                input[3] = [ [], [] ]
                input[4] = [ [], [], [] ]
                input[5] = 'bam'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out,
                    path(process.out.compatible_versions.get(0)).yaml
                    ).match() }
            )
        }
    }

    test("sarscov2 - fastq - pe") {

        when {
            params {
                module_args = ''
                bwa_prefix = 'genome.fasta'
            }
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = BWA_INDEX_PE.out.index
                input[3] = [ [], [] ]
                input[4] = [ [], [], [] ]
                input[5] = 'bam'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    file(process.out.bai[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }

    }

    test("sarscov2 - fastq - pe - stub") {

        options '-stub'

        when {
            params {
                module_args = ''
                bwa_prefix = ''
            }
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = BWA_INDEX_PE.out.index
                input[3] = [ [], [] ]
                input[4] = [ [], [], [] ]
                input[5] = 'bam'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out,
                    path(process.out.compatible_versions.get(0)).yaml
                    ).match() }
            )
        }

    }

    test("sarscov2 - fastq - se - cram") {

        when {
            params {
                module_args = ''
                bwa_prefix = 'genome.fasta'
            }
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = [[id: 'test'],file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                input[2] = BWA_INDEX_CRAM.out.index
                input[3] = [ [], [] ]
                input[4] = [ [], [], [] ]
                input[5] = 'cram'
                """
            }
        }

        then {
            def fasta = "https://raw.githubusercontent.com/nf-core/test-datasets/refs/heads/modules/data/genomics/sarscov2/genome/genome.fasta"
            assertAll(
                { assert process.success },
                { assert snapshot(
                    cram(
                        process.out.cram[0][1],
                        fasta,
                        ).getReadsMD5(),
                    file(process.out.crai[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }

    }

    test("sarscov2 - fastq - pe - cram - stub") {

        options '-stub'

        when {
            params {
                module_args = ''
                bwa_prefix = ''
            }
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = BWA_INDEX_PE.out.index
                input[3] = [ [], [] ]
                input[4] = [ [], [], [] ]
                input[5] = 'cram'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match()}
            )
        }

    }

}

